-- Greece deep-dive ES/DE/FR translations (completing 240). INSERT OR IGNORE.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es', 'Modelo de compensación (myDATA) — el mandato B2B se despliega a lo largo de 2026', 'Esta página de análisis refleja la orientación pública y las noticias disponibles a principios de agosto de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. El mandato B2B nacional de Grecia seguía en su despliegue de Fase 2 en el momento de redactar esto — confirme el estado actual directamente con AADE antes de basarse en ella.', 'Grecia opera uno de los sistemas de compensación más maduros de este rastreador: myDATA exige el reporte en tiempo real de cada factura desde 2021, la facturación electrónica B2G es totalmente obligatoria desde septiembre de 2025, y un mandato B2B nacional se está desplegando ahora en dos fases a lo largo de 2026 — la Fase 1 (empresas con ingresos superiores a 1 millón de euros) entró en vigor el 2 de marzo de 2026 y ya está vigente; la Fase 2 amplía la obligación a todas las empresas restantes a partir del 1 de octubre de 2026.', 'Se aplican dos normas relacionadas pero distintas según el tipo de transacción: EN 16931 a través del CIUS griego de Peppol para B2G, y facturas basadas en EN 16931 validadas a través del sistema de compensación myDATA para B2B — de forma notable, Peppol no es la vía de intercambio obligatoria para B2B, a diferencia del B2G.', 'Cada factura, B2G o B2B, es validada por myDATA y recibe una marca de registro única (MARK) y un código QR antes de tener efecto legal — un genuino modelo de compensación previa, no de reporte posterior a la transacción. Las facturas B2G pasan después a los organismos públicos a través de puntos de acceso Peppol acreditados; las facturas B2B se mueven a través de proveedores de facturación electrónica certificados, la aplicación gratuita Timologio de AADE, o la integración directa del ERP a través de la API REST de myDATA.', 'Con la Fase 1 del mandato B2B nacional ya vigente y la Fase 2 acercándose en octubre de 2026, la mayor parte del trabajo a corto plazo de las empresas es genuinamente urgente, no exploratorio — confirmar una vía de cumplimiento, comprobar qué fase se aplica y entender el alcance real del mandato (solo B2B nacional y con terceros países; el B2B intracomunitario sigue siendo opcional por ahora).', 'No emitir una factura electrónica requerida se trata como la no emisión de la propia factura — una sanción real y sustancial (50% del IVA que hubiera resultado), no una mera formalidad de procedimiento, lo que refleja el propósito subyacente del modelo de compensación de cerrar la brecha del IVA.', 'La plataforma myDATA de Grecia exige el reporte en tiempo real de facturas y contabilidad desde 2021, asignando a cada transacción una MARK única y un código QR. La facturación electrónica B2G se volvió totalmente obligatoria en septiembre de 2025 tras un despliegue por fases entre 2023 y 2025. Un mandato B2B nacional está ahora vigente: la Fase 1 (empresas con ingresos superiores a 1 millón de euros) entró en vigor el 2 de marzo de 2026 bajo una excepción de la UE (Decisión de Ejecución (UE) 2025/502 del Consejo); la Fase 2 amplía la obligación a todas las empresas restantes a partir del 1 de octubre de 2026, con un período de adaptación hasta fin de año. El mandato cubre el B2B nacional y las ventas B2B a entidades no pertenecientes a la UE; el B2B intracomunitario sigue siendo opcional. Por separado, el mandato de ViDA de facturación electrónica y reporte transfronterizos B2B es derecho de la UE confirmado desde el 1 de julio de 2030.', '🇬🇷' FROM countries WHERE name_en = 'Greece';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de', 'Clearance-Modell (myDATA) — die B2B-Pflicht wird 2026 stufenweise eingeführt', 'Diese Länderanalyse spiegelt öffentlich verfügbare Hinweise und Berichterstattung mit Stand Anfang August 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Griechenlands inländische B2B-Pflicht befand sich zum Zeitpunkt der Abfassung noch in der Einführung von Phase 2 — bestätigen Sie den aktuellen Stand direkt bei der AADE, bevor Sie darauf aufbauen.', 'Griechenland betreibt eines der ausgereifteren Clearance-Systeme in diesem Tracker: myDATA verlangt seit 2021 die Echtzeitmeldung jeder Rechnung, die B2G-E-Rechnung ist seit September 2025 vollständig verpflichtend, und eine inländische B2B-Pflicht wird nun in zwei Phasen bis 2026 eingeführt — Phase 1 (Unternehmen mit einem Umsatz über 1 Million Euro) trat am 2. März 2026 in Kraft und gilt bereits; Phase 2 weitet die Pflicht ab dem 1. Oktober 2026 auf alle verbleibenden Unternehmen aus.', 'Je nach Umsatzart gelten zwei verwandte, aber unterschiedliche Standards: EN 16931 über das griechische Peppol-CIUS für B2G, und auf EN 16931 basierende Rechnungen, die über das myDATA-Clearance-System validiert werden, für B2B — bemerkenswert ist, dass Peppol im Gegensatz zu B2G nicht der verpflichtende Austauschweg für B2B ist.', 'Jede Rechnung, ob B2G oder B2B, wird von myDATA validiert und erhält vor Rechtswirksamkeit eine eindeutige Registrierungsmarke (MARK) und einen QR-Code — ein echtes Vorab-Clearance-Modell, kein Modell der Meldung nach der Transaktion. B2G-Rechnungen gelangen anschließend über akkreditierte Peppol-Zugangspunkte an öffentliche Stellen; B2B-Rechnungen laufen über zertifizierte E-Rechnungsanbieter, die kostenlose Timologio-App der AADE oder die direkte ERP-Integration über die myDATA-REST-API.', 'Da Phase 1 der inländischen B2B-Pflicht bereits in Kraft ist und Phase 2 im Oktober 2026 näherrückt, ist die kurzfristige Arbeit der meisten Unternehmen tatsächlich zeitkritisch statt explorativ — einen Erfüllungsweg bestätigen, prüfen, welche Phase gilt, und den tatsächlichen Umfang der Pflicht verstehen (nur inländisches und Nicht-EU-B2B; innergemeinschaftliches B2B bleibt vorerst freiwillig).', 'Die Nichtausstellung einer erforderlichen E-Rechnung wird rechtlich als Nichtausstellung der Rechnung selbst behandelt — eine echte, erhebliche Sanktion (50 % der andernfalls entstandenen Umsatzsteuer), keine bloße verfahrenstechnische Formalität, was den zugrunde liegenden Zweck des Clearance-Modells widerspiegelt, die Umsatzsteuerlücke zu schließen.', 'Griechenlands myDATA-Plattform verlangt seit 2021 die Echtzeitmeldung von Rechnungs- und Buchhaltungsdaten und vergibt für jede Transaktion eine eindeutige MARK und einen QR-Code. Die B2G-E-Rechnung wurde im September 2025 nach einer stufenweisen Einführung zwischen 2023 und 2025 vollständig verpflichtend. Eine inländische B2B-Pflicht ist nun in Kraft: Phase 1 (Unternehmen mit einem Umsatz über 1 Million Euro) trat am 2. März 2026 im Rahmen einer EU-Ausnahmeregelung (Durchführungsbeschluss (EU) 2025/502 des Rates) in Kraft; Phase 2 weitet die Pflicht ab dem 1. Oktober 2026 auf alle verbleibenden Unternehmen aus, mit einer Anpassungsfrist bis Jahresende. Die Pflicht umfasst inländisches B2B und B2B-Verkäufe an Nicht-EU-Einheiten; innergemeinschaftliches B2B bleibt freiwillig. Unabhängig davon ist ViDAs grenzüberschreitende B2B-E-Rechnungs- und Meldepflicht ab dem 1. Juli 2030 bestätigtes EU-Recht.', '🇬🇷' FROM countries WHERE name_en = 'Greece';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr', 'Modèle de validation préalable (myDATA) — l''obligation B2B se déploie tout au long de 2026', 'Cette analyse par pays reflète les informations publiques et l''actualité disponibles début août 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. L''obligation B2B nationale de la Grèce en était encore au déploiement de la phase 2 au moment de la rédaction — confirmez le statut actuel directement auprès de l''AADE avant de vous y fier.', 'La Grèce exploite l''un des systèmes de validation préalable les plus matures de ce tracker : myDATA exige la déclaration en temps réel de chaque facture depuis 2021, la facturation électronique B2G est entièrement obligatoire depuis septembre 2025, et une obligation B2B nationale se déploie désormais en deux phases tout au long de 2026 — la phase 1 (entreprises dont le chiffre d''affaires dépasse 1 million d''euros) est entrée en vigueur le 2 mars 2026 et s''applique déjà ; la phase 2 étend l''obligation à toutes les entreprises restantes à partir du 1er octobre 2026.', 'Deux normes apparentées mais distinctes s''appliquent selon le type de transaction : l''EN 16931 via le CIUS Peppol grec pour le B2G, et des factures basées sur l''EN 16931 validées via le système de validation préalable myDATA pour le B2B — notamment, Peppol n''est pas la voie d''échange obligatoire pour le B2B, contrairement au B2G.', 'Chaque facture, B2G ou B2B, est validée par myDATA et reçoit une marque d''enregistrement unique (MARK) et un code QR avant d''avoir un effet juridique — un véritable modèle de validation préalable, non un modèle de déclaration post-transaction. Les factures B2G transitent ensuite vers les organismes publics via des points d''accès Peppol accrédités ; les factures B2B transitent via des fournisseurs de facturation électronique certifiés, l''application gratuite Timologio de l''AADE, ou l''intégration ERP directe via l''API REST myDATA.', 'La phase 1 de l''obligation B2B nationale étant déjà en vigueur et la phase 2 approchant en octobre 2026, l''essentiel du travail à court terme des entreprises est véritablement urgent plutôt qu''exploratoire — confirmer une voie de conformité, vérifier quelle phase s''applique, et comprendre le périmètre réel de l''obligation (seulement le B2B national et hors UE ; le B2B intracommunautaire reste optionnel pour l''instant).', 'Le défaut d''émission d''une facture électronique requise est traité juridiquement comme une non-émission de la facture elle-même — une sanction réelle et substantielle (50 % de la TVA qui en aurait résulté), non une simple formalité procédurale, reflétant l''objectif sous-jacent du modèle de validation préalable de combler l''écart de TVA.', 'La plateforme myDATA de la Grèce exige la déclaration en temps réel des factures et de la comptabilité depuis 2021, attribuant à chaque transaction une MARK unique et un code QR. La facturation électronique B2G est devenue entièrement obligatoire en septembre 2025 après un déploiement progressif entre 2023 et 2025. Une obligation B2B nationale est désormais en vigueur : la phase 1 (entreprises dont le chiffre d''affaires dépasse 1 million d''euros) est entrée en vigueur le 2 mars 2026 dans le cadre d''une dérogation de l''UE (décision d''exécution (UE) 2025/502 du Conseil) ; la phase 2 étend l''obligation à toutes les entreprises restantes à partir du 1er octobre 2026, avec une période d''adaptation jusqu''à la fin de l''année. L''obligation couvre le B2B national et les ventes B2B à des entités hors UE ; le B2B intracommunautaire reste optionnel. Par ailleurs, l''obligation ViDA de facturation électronique et de déclaration transfrontalières B2B est un droit de l''UE confirmé à partir du 1er juillet 2030.', '🇬🇷' FROM countries WHERE name_en = 'Greece';

