INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Formato y estándar', '[["Formato B2G", "EN 16931 a través del CIUS griego de Peppol"], ["Formato B2B", "Basado en EN 16931, validado a través de la compensación myDATA — Peppol no es la vía de intercambio obligatoria"], ["Base legal", "Ley 4972/2022 (B2G); Decisión de Ejecución (UE) 2025/502 del Consejo (excepción B2B)"], ["Validación", "Cada factura recibe una MARK (marca de registro única) y un código QR de myDATA antes de tener efecto legal"]]', 'El requisito de MARK/QR se aplica de manera uniforme tanto al B2G como al B2B — la diferencia real está en el canal de transmisión, no en el paso de validación subyacente.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Greece' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Format & Standard', '[["B2G-Format", "EN 16931 über das griechische Peppol-CIUS"], ["B2B-Format", "Auf EN 16931 basierend, validiert über die myDATA-Clearance — Peppol ist nicht der verpflichtende Austauschweg"], ["Rechtsgrundlage", "Gesetz 4972/2022 (B2G); Durchführungsbeschluss (EU) 2025/502 des Rates (B2B-Ausnahme)"], ["Validierung", "Jede Rechnung erhält vor Rechtswirksamkeit eine MARK (eindeutige Registrierungsmarke) und einen QR-Code von myDATA"]]', 'Die MARK/QR-Anforderung gilt einheitlich für B2G und B2B — der eigentliche Unterschied liegt im Übermittlungskanal, nicht im zugrunde liegenden Validierungsschritt.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Greece' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Format et norme', '[["Format B2G", "EN 16931 via le CIUS Peppol grec"], ["Format B2B", "Basé sur l''EN 16931, validé via la validation préalable myDATA — Peppol n''est pas la voie d''échange obligatoire"], ["Base légale", "Loi 4972/2022 (B2G) ; décision d''exécution (UE) 2025/502 du Conseil (dérogation B2B)"], ["Validation", "Chaque facture reçoit une MARK (marque d''enregistrement unique) et un code QR de myDATA avant d''avoir un effet juridique"]]', 'L''exigence MARK/QR s''applique uniformément au B2G et au B2B — la véritable différence réside dans le canal de transmission, non dans l''étape de validation sous-jacente.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Greece' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Identificadores y registro', '[["B2G", "Se requiere un punto de acceso Peppol acreditado"], ["B2B", "Proveedor de facturación electrónica certificado, la aplicación gratuita Timologio de AADE, o integración directa del ERP a través de la API REST de myDATA"], ["Organismo supervisor", "AADE — Autoridad Independiente de Ingresos Públicos"], ["Umbral (Fase 1)", "Ingresos anuales superiores a 1 millón de euros"]]', 'A diferencia de muchos pares, Grecia ofrece una vía de cumplimiento genuinamente gratuita (Timologio) junto a proveedores comerciales certificados — vale la pena comprobarlo antes de asumir que se necesita una solución de pago.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Greece' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Kennungen & Registrierung', '[["B2G", "Ein akkreditierter Peppol-Zugangspunkt ist erforderlich"], ["B2B", "Zertifizierter E-Rechnungsanbieter, die kostenlose Timologio-App der AADE, oder direkte ERP-Integration über die myDATA-REST-API"], ["Aufsichtsbehörde", "AADE — die unabhängige Behörde für öffentliche Einnahmen"], ["Schwelle (Phase 1)", "Jahresumsatz über 1 Million Euro"]]', 'Anders als viele Vergleichsländer bietet Griechenland neben zertifizierten kommerziellen Anbietern einen echten kostenlosen Erfüllungsweg (Timologio) — es lohnt sich zu prüfen, bevor man von einer kostenpflichtigen Lösung ausgeht.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Greece' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Identifiants et enregistrement', '[["B2G", "Un point d''accès Peppol accrédité est requis"], ["B2B", "Fournisseur de facturation électronique certifié, application gratuite Timologio de l''AADE, ou intégration ERP directe via l''API REST myDATA"], ["Organisme de contrôle", "AADE — Autorité indépendante des recettes publiques"], ["Seuil (phase 1)", "Chiffre d''affaires annuel supérieur à 1 million d''euros"]]', 'Contrairement à de nombreux pairs, la Grèce propose une voie de conformité véritablement gratuite (Timologio) aux côtés de fournisseurs commerciaux certifiés — cela vaut la peine d''être vérifié avant de supposer qu''une solution payante est nécessaire.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Greece' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Contenido obligatorio', '[["Modelo básico", "Modelo de datos semántico completo de EN 16931"], ["Alcance B2B", "Transacciones nacionales y ventas a entidades no pertenecientes a la UE — el B2B intracomunitario sigue siendo opcional por ahora"], ["Archivo", "Se aplica el requisito estándar griego de conservación de registros"]]', 'La exclusión del B2B intracomunitario es un matiz genuino a tener en cuenta — una empresa griega que vende a una contraparte alemana aún no está obligada a facturar electrónicamente esa transacción concreta, aunque sí lo estén sus ventas nacionales y a terceros países.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Greece' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Pflichtinhalte', '[["Kernmodell", "Vollständiges semantisches Datenmodell nach EN 16931"], ["B2B-Umfang", "Inländische Umsätze und Verkäufe an Nicht-EU-Einheiten — innergemeinschaftliches B2B bleibt vorerst freiwillig"], ["Archivierung", "Es gilt die griechische Standard-Aufbewahrungspflicht"]]', 'Die Ausnahme für innergemeinschaftliches B2B ist eine echte Nuance, die es zu beachten gilt — ein griechisches Unternehmen, das an einen deutschen Geschäftspartner verkauft, ist für diesen konkreten Umsatz noch nicht zur E-Rechnung verpflichtet, obwohl dies für seine inländischen und Nicht-EU-Verkäufe bereits gilt.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Greece' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Contenu obligatoire', '[["Modèle de base", "Modèle de données sémantique complet EN 16931"], ["Périmètre B2B", "Transactions nationales et ventes à des entités hors UE — le B2B intracommunautaire reste optionnel pour l''instant"], ["Archivage", "L''exigence standard grecque de conservation des documents s''applique"]]', 'L''exclusion du B2B intracommunautaire est une nuance réelle à noter — une entreprise grecque vendant à une contrepartie allemande n''est pas encore tenue de facturer électroniquement cette transaction spécifique, même si ses ventes nationales et hors UE le sont.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Greece' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Modelo de red', '[["Modelo", "Compensación previa genuina — myDATA valida y asigna MARK a cada factura antes de que tenga efecto legal"], ["Transmisión B2G", "Puntos de acceso Peppol acreditados al Centro Nacional de Interoperabilidad (KED)"], ["Transmisión B2B", "Proveedores certificados, Timologio, o API REST directa de myDATA — no necesariamente Peppol"], ["Reporte en tiempo real", "Sí — myDATA lo exige desde 2021, antes incluso del propio mandato de facturación electrónica"]]', 'La secuencia de Grecia, primero el reporte y después la facturación, es inusual — la mayoría de los países con compensación construyeron el mandato y el sistema de reporte a la vez, mientras que Grecia tuvo años de datos de reporte myDATA en vivo antes de añadir un mandato completo de facturación electrónica.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Greece' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Netzwerkmodell', '[["Modell", "Echtes Vorab-Clearance — myDATA validiert und vergibt für jede Rechnung vor Rechtswirksamkeit ein MARK"], ["B2G-Übermittlung", "Akkreditierte Peppol-Zugangspunkte an das nationale Interoperabilitätszentrum (KED)"], ["B2B-Übermittlung", "Zertifizierte Anbieter, Timologio oder direkte myDATA-REST-API — nicht zwingend Peppol"], ["Echtzeit-Meldung", "Ja — myDATA verlangt dies bereits seit 2021, noch vor der eigentlichen E-Rechnungspflicht"]]', 'Griechenlands Reihenfolge — zuerst Meldung, dann Rechnungsstellung — ist ungewöhnlich: Die meisten Clearance-Länder haben Pflicht und Meldesystem gemeinsam aufgebaut, während Griechenland jahrelange myDATA-Live-Meldedaten hatte, bevor eine vollständige E-Rechnungspflicht darauf aufgesetzt wurde.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Greece' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Modèle de réseau', '[["Modèle", "Véritable validation préalable — myDATA valide et attribue une MARK à chaque facture avant qu''elle n''ait un effet juridique"], ["Transmission B2G", "Points d''accès Peppol accrédités vers le Centre national d''interopérabilité (KED)"], ["Transmission B2B", "Fournisseurs certifiés, Timologio, ou API REST myDATA directe — pas nécessairement Peppol"], ["Déclaration en temps réel", "Oui — myDATA l''exige depuis 2021, avant même l''obligation de facturation électronique elle-même"]]', 'La séquence de la Grèce — d''abord la déclaration, puis la facturation — est inhabituelle : la plupart des pays à validation préalable ont construit l''obligation et le système de déclaration ensemble, tandis que la Grèce disposait de plusieurs années de données de déclaration myDATA en direct avant d''ajouter une obligation complète de facturation électronique.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Greece' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Fases de implantación', '[["Fase 1", "2 de marzo de 2026 — empresas con ingresos superiores a 1 millón de euros (vigente)"], ["Período de transición", "Hasta el 3 de mayo de 2026 — aplicación gradual para fallos técnicos aislados"], ["Fase 2", "1 de octubre de 2026 — todas las empresas restantes"], ["Período de adaptación", "Hasta el 31 de diciembre de 2026"]]', 'La Fase 1 ya está vigente hoy — no es un hito futuro para el que planificar, es una obligación actual y activa para las empresas por encima del umbral de ingresos.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Greece' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Einführungsphasen', '[["Phase 1", "2. März 2026 — Unternehmen mit einem Umsatz über 1 Million Euro (in Kraft)"], ["Übergangsfrist", "Bis 3. Mai 2026 — abgestufte Durchsetzung bei isolierten technischen Ausfällen"], ["Phase 2", "1. Oktober 2026 — alle verbleibenden Unternehmen"], ["Anpassungsfrist", "Bis 31. Dezember 2026"]]', 'Phase 1 ist bereits heute in Kraft — das ist kein zukünftiger Meilenstein zur Planung, sondern eine aktuelle, aktive Pflicht für Unternehmen oberhalb der Umsatzschwelle.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Greece' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Phases de déploiement', '[["Phase 1", "2 mars 2026 — entreprises dont le chiffre d''affaires dépasse 1 million d''euros (en vigueur)"], ["Période de transition", "Jusqu''au 3 mai 2026 — application graduée pour les défaillances techniques isolées"], ["Phase 2", "1er octobre 2026 — toutes les entreprises restantes"], ["Période d''adaptation", "Jusqu''au 31 décembre 2026"]]', 'La phase 1 est déjà en vigueur aujourd''hui — ce n''est pas un jalon futur à planifier, c''est une obligation actuelle et active pour les entreprises au-dessus du seuil de chiffre d''affaires.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Greece' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Límites del alcance', '[["Obligatorio", "B2B nacional; ventas B2B a entidades no pertenecientes a la UE"], ["Aún no obligatorio", "B2B intracomunitario (sigue siendo opcional)"], ["No cubierto", "Transacciones B2C — no existe un marco obligatorio de facturación electrónica B2C"], ["Excepción de la UE", "La Decisión de Ejecución (UE) 2025/502 del Consejo autoriza el mandato nacional antes del calendario general de ViDA"]]', 'Las empresas deben comprobar cuidadosamente la ubicación de cada contraparte — las obligaciones de una empresa griega difieren de forma significativa según si un comprador es nacional, de otro estado de la UE, o de fuera de la UE.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Greece' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Umfangsgrenzen', '[["Verpflichtend", "Inländisches B2B; B2B-Verkäufe an Nicht-EU-Einheiten"], ["Noch nicht verpflichtend", "Innergemeinschaftliches B2B (bleibt freiwillig)"], ["Nicht erfasst", "B2C-Umsätze — es gibt keinen verpflichtenden B2C-E-Rechnungsrahmen"], ["EU-Ausnahme", "Der Durchführungsbeschluss (EU) 2025/502 des Rates ermächtigt die inländische Pflicht vor dem allgemeinen ViDA-Zeitplan"]]', 'Unternehmen sollten den Standort jedes Geschäftspartners sorgfältig prüfen — die Pflichten eines griechischen Unternehmens unterscheiden sich erheblich, je nachdem, ob ein Käufer inländisch, in einem anderen EU-Staat oder außerhalb der EU ansässig ist.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Greece' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Limites du périmètre', '[["Obligatoire", "B2B national ; ventes B2B à des entités hors UE"], ["Pas encore obligatoire", "B2B intracommunautaire (reste optionnel)"], ["Non couvert", "Transactions B2C — aucun cadre obligatoire de facturation électronique B2C"], ["Dérogation de l''UE", "La décision d''exécution (UE) 2025/502 du Conseil autorise l''obligation nationale avant le calendrier général de ViDA"]]', 'Les entreprises doivent vérifier attentivement la localisation de chaque contrepartie — les obligations d''une entreprise grecque diffèrent sensiblement selon qu''un acheteur est national, situé dans un autre État de l''UE, ou hors UE.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Greece' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '⚖️ Sanción por no emisión', NULL, NULL, 'No emitir una factura electrónica requerida se considera legalmente como la no emisión de la propia factura, lo que activa una multa del 50% del IVA que hubiera resultado — una sanción sustancial vinculada a los ingresos, no una tarifa administrativa fija.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Greece' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '⚖️ Sanktion bei Nichtausstellung', NULL, NULL, 'Die Nichtausstellung einer erforderlichen E-Rechnung gilt rechtlich als Nichtausstellung der Rechnung selbst und löst eine Geldstrafe in Höhe von 50 % der andernfalls entstandenen Umsatzsteuer aus — eine erhebliche, umsatzbezogene Sanktion und keine pauschale Verwaltungsgebühr.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Greece' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '⚖️ Sanction pour non-émission', NULL, NULL, 'Le défaut d''émission d''une facture électronique requise est légalement traité comme une non-émission de la facture elle-même, déclenchant une amende de 50 % de la TVA qui en aurait résulté — une sanction substantielle liée au chiffre d''affaires, non des frais administratifs forfaitaires.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Greece' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🕐 Aplicación gradual durante la transición', NULL, NULL, 'AADE aplicó una ejecución gradual hasta el 3 de mayo de 2026 para las empresas en el período de transición de la Fase 1 — los fallos técnicos aislados no activaron el marco sancionador completo, aunque se esperaba que todas las empresas cubiertas estuvieran plenamente operativas al final del período.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Greece' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🕐 Abgestufte Durchsetzung während der Übergangsphase', NULL, NULL, 'Die AADE wandte bis zum 3. Mai 2026 eine abgestufte Durchsetzung für Unternehmen in der Übergangsphase von Phase 1 an — isolierte technische Ausfälle lösten nicht das volle Sanktionsregime aus, wobei erwartet wurde, dass alle betroffenen Unternehmen bis zum Ende der Frist vollständig einsatzbereit sind.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Greece' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🕐 Application graduée pendant la transition', NULL, NULL, 'L''AADE a appliqué une application graduée jusqu''au 3 mai 2026 pour les entreprises en période de transition de la phase 1 — des défaillances techniques isolées n''ont pas déclenché le régime de sanctions complet, bien que toutes les entreprises concernées devaient être pleinement opérationnelles à la fin de la période.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Greece' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🇪🇺 El suelo de la UE que se acerca', NULL, NULL, 'Con independencia del alcance propio del mandato nacional, el requisito transfronterizo de ViDA es derecho de la UE confirmado desde el 1 de julio de 2030 — toda empresa griega que realice comercio B2B intracomunitario necesitará finalmente facturación electrónica y reporte digital conformes con EN 16931 también para esas transacciones concretas.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Greece' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🇪🇺 Die näherrückende EU-Untergrenze', NULL, NULL, 'Unabhängig vom Umfang der inländischen Pflicht ist die grenzüberschreitende ViDA-Anforderung ab dem 1. Juli 2030 bestätigtes EU-Recht — jedes griechische Unternehmen mit innergemeinschaftlichem B2B-Handel wird letztlich auch für diese konkreten Umsätze EN-16931-konforme E-Rechnung und digitale Meldung benötigen.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Greece' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🇪🇺 Le plancher de l''UE qui approche', NULL, NULL, 'Quel que soit le périmètre propre de l''obligation nationale, l''exigence transfrontalière de ViDA est un droit de l''UE confirmé à partir du 1er juillet 2030 — toute entreprise grecque réalisant du commerce B2B intracommunautaire aura finalement besoin d''une facturation électronique et d''une déclaration numérique conformes à l''EN 16931 pour ces transactions spécifiques également.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Greece' AND dc.section = 'penalties_related' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme qué fase se aplica a su empresa', 'La Fase 1 (ingresos superiores a 1 millón de euros) ya está vigente desde el 2 de marzo de 2026; la Fase 2 (todas las empresas restantes) entra en vigor el 1 de octubre de 2026.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Greece' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bestätigen Sie, welche Phase für Ihr Unternehmen gilt', 'Phase 1 (Umsatz über 1 Million Euro) ist bereits seit dem 2. März 2026 in Kraft; Phase 2 (alle verbleibenden Unternehmen) tritt am 1. Oktober 2026 in Kraft.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Greece' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Confirmez quelle phase s''applique à votre entreprise', 'La phase 1 (chiffre d''affaires supérieur à 1 million d''euros) est déjà en vigueur depuis le 2 mars 2026 ; la phase 2 (toutes les entreprises restantes) entre en vigueur le 1er octobre 2026.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Greece' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Elija su vía de cumplimiento', 'Un proveedor comercial certificado de facturación electrónica, la aplicación gratuita Timologio de AADE, o la integración directa del ERP a través de la API REST de myDATA — todas son válidas, y Timologio es una opción genuinamente gratuita que vale la pena evaluar.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Greece' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wählen Sie Ihren Erfüllungsweg', 'Ein zertifizierter kommerzieller E-Rechnungsanbieter, die kostenlose Timologio-App der AADE oder die direkte ERP-Integration über die myDATA-REST-API — alle sind gültig, und Timologio ist eine echte kostenlose Option, die es zu prüfen lohnt.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Greece' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Choisissez votre voie de conformité', 'Un fournisseur commercial certifié de facturation électronique, l''application gratuite Timologio de l''AADE, ou l''intégration ERP directe via l''API REST myDATA — toutes sont valables, et Timologio est une option véritablement gratuite qui mérite d''être évaluée.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Greece' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Clasifique a sus contrapartes por ubicación', 'El mandato cubre el B2B nacional y las ventas B2B a terceros países, pero aún no el B2B intracomunitario — confirme cuáles de sus transacciones están realmente en el alcance antes de asumir que se requiere cobertura completa.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Greece' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Ordnen Sie Ihre Geschäftspartner nach Standort ein', 'Die Pflicht umfasst inländisches B2B und B2B-Verkäufe an Nicht-EU-Länder, aber noch nicht innergemeinschaftliches B2B — bestätigen Sie, welche Ihrer Umsätze tatsächlich erfasst sind, bevor Sie von einer vollständigen Abdeckung ausgehen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Greece' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Cartographiez vos contreparties par localisation', 'L''obligation couvre le B2B national et les ventes B2B hors UE, mais pas encore le B2B intracommunautaire — confirmez lesquelles de vos transactions sont réellement dans le périmètre avant de supposer qu''une couverture complète est requise.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Greece' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme que su generación de MARK/QR de myDATA es correcta', 'Cada factura necesita una MARK y un código QR válidos de myDATA antes de tener efecto legal — esto se aplica desde 2021 y sigue siendo fundamental para el nuevo mandato B2B.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Greece' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bestätigen Sie, dass Ihre myDATA-MARK/QR-Generierung korrekt ist', 'Jede Rechnung benötigt vor Rechtswirksamkeit ein gültiges MARK und einen QR-Code von myDATA — dies gilt seit 2021 und bleibt grundlegend für die neuere B2B-Pflicht.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Greece' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Confirmez que votre génération MARK/QR myDATA est correcte', 'Chaque facture a besoin d''une MARK valide et d''un code QR de myDATA avant d''avoir un effet juridique — cela s''applique depuis 2021 et reste fondamental pour la nouvelle obligation B2B.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Greece' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Prepárese para el suelo transfronterizo de 2030 en cualquier caso', 'Una vez que el requisito transfronterizo de ViDA entre en vigor el 1 de julio de 2030, las transacciones B2B intracomunitarias también necesitarán facturación electrónica y reporte digital conforme a EN 16931, independientemente de las decisiones de alcance nacional propias de Grecia.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Greece' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bereiten Sie sich in jedem Fall auf die grenzüberschreitende Untergrenze 2030 vor', 'Sobald die grenzüberschreitende ViDA-Anforderung am 1. Juli 2030 in Kraft tritt, benötigen auch innergemeinschaftliche B2B-Umsätze EN-16931-konforme E-Rechnung und digitale Meldung, unabhängig von Griechenlands eigenen inländischen Umfangsentscheidungen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Greece' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Préparez-vous au plancher transfrontalier de 2030 dans tous les cas', 'Une fois l''exigence transfrontalière de ViDA en vigueur le 1er juillet 2030, les transactions B2B intracommunautaires nécessiteront elles aussi une facturation électronique et une déclaration numérique conformes à l''EN 16931, indépendamment des décisions de périmètre national propres à la Grèce.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Greece' AND ds.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'es', 'AADE — myDATA' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Greece' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'de', 'AADE — myDATA' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Greece' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'fr', 'AADE — myDATA' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Greece' AND dp.sort_order = 0;
